///////////////////////////////////   MUX   ////////////////////////////////////

module MX2X1 (A,B,S0, Y);
	input 	A,B;	
	input		S0;
	output 	Y;

	assign	Y= (~S0 & A)|(S0 & B);	
endmodule

module MX2X2 (A,B,S0, Y);
	input 	A,B;	
	input		S0;
	output 	Y;

	assign	Y= (~S0 & A)|(S0 & B);	
endmodule

module MX4X1 (A,B,C,D,S0,S1, Y);
	input 	A,B,C,D;
	input		S0,S1;
	output 	Y;
	
	assign	Y= 	(~S0 & ~S1 & A)|
						( S0 & ~S1 & B)|
						(~S0 &  S1 & C)|
						( S0 &  S1 & D);	
endmodule

////////////////////////////////////////////////////////////////////////////////

/////////////////////////////////   F / F   ////////////////////////////////////

module SDFFRHQX2 (D, SI, SE, CK, RN, Q );
	input 	D, SI, SE, CK, RN;
	output	Q;
	reg		Q;
	
	always @(posedge CK)//or posedge SE or posedge RN 
		if( !RN )	 		Q <= 0;
		else if(SE)		Q <= SI;
		else	 			Q <= D;
endmodule

module SDFFRX2 (D, SI, SE, CK, RN, Q, QN);
	input 	D, SI, SE, CK, RN;
	output	Q, QN;
	reg		Q, QN;
	
	always @(posedge CK )// or posedge SE or posedge RN
		if( !RN )		begin 	Q <= 0;		QN <= 1;	end
		else if(SE)	begin		Q <= SI; 	QN <= ~SI;	end
		else	 		begin		Q <= D;		QN <= ~D;	end
endmodule

module SDFFSHQX1 (D, SI, SE, CK, SN, Q);
	input 	D, SI, SE, CK, SN;
	output	Q;
	reg		Q;
	
	always @(posedge CK )// or posedge SE or negedge SN
		if( !SN )	 	Q <= 1;
		else if(SE)		Q <= SI;
		else	 			Q <= D;
endmodule

////////////////////////////////////////////////////////////////////////////////

/////////////////////////////////   ADDER   ////////////////////////////////////

module ADDHX1 (A,B,S,CO);
	input		A,B;
	output	S,CO;
	
	assign	CO = A & B;
	assign	S  = A ^ B;

endmodule

module ADDFHX1 (A,B,CI,S,CO);
	input		A,B,CI;
	output	S,CO;
	
	wire		S0,C0,C1;
	
	assign	S0 = A ^ B;
	assign	C0 = A & B;
	assign	C1 = S0 & CI;
	assign	CO = C0 | C1;
	assign	S  = S0 ^ CI;
	
endmodule

